#!/bin/bash
# ================================================================
#  KI-Vault Chrome Extension — Linux Installer
#  Alle Dateien eingebettet. Kein Internet nötig.
#  Ausführen: bash ki-vault-install.sh
# ================================================================

set -e

CYAN="\033[0;36m"
GREEN="\033[0;32m"
YELLOW="\033[1;33m"
GRAY="\033[0;90m"
NC="\033[0m"

DEST="$HOME/Desktop/ki-vault-extension"

clear 2>/dev/null || true
echo ""
echo -e "  ${CYAN}╔══════════════════════════════════════════╗${NC}"
echo -e "  ${CYAN}║   🏛️  KI-VAULT CHROME EXTENSION           ║${NC}"
echo -e "  ${CYAN}║       Linux Installer v1.0               ║${NC}"
echo -e "  ${CYAN}╚══════════════════════════════════════════╝${NC}"
echo ""

# ── STEP 1: ORDNER ───────────────────────────────────────────────────
echo -e "  ${YELLOW}[1/4]${NC} Erstelle Extension-Ordner..."
rm -rf "$DEST"
mkdir -p "$DEST/icons" "$DEST/content" "$DEST/src"
echo -e "         ${GREEN}✅ $DEST${NC}"

# ── STEP 2: DATEIEN SCHREIBEN ────────────────────────────────────────
echo -e "  ${YELLOW}[2/4]${NC} Schreibe alle Extension-Dateien..."

echo -e "         ${GRAY}README.md${NC}"
mkdir -p "$DEST/$(dirname "README.md")"
echo "" | base64 -d > "$DEST/README.md"

echo -e "         ${GRAY}content/chatgpt.js${NC}"
mkdir -p "$DEST/$(dirname "content/chatgpt.js")"
echo "" | base64 -d > "$DEST/content/chatgpt.js"

echo -e "         ${GRAY}content/claude.js${NC}"
mkdir -p "$DEST/$(dirname "content/claude.js")"
echo "" | base64 -d > "$DEST/content/claude.js"

echo -e "         ${GRAY}content/gemini.js${NC}"
mkdir -p "$DEST/$(dirname "content/gemini.js")"
echo "" | base64 -d > "$DEST/content/gemini.js"

echo -e "         ${GRAY}content/perplexity.js${NC}"
mkdir -p "$DEST/$(dirname "content/perplexity.js")"
echo "" | base64 -d > "$DEST/content/perplexity.js"

echo -e "         ${GRAY}content/shared.js${NC}"
mkdir -p "$DEST/$(dirname "content/shared.js")"
echo "" | base64 -d > "$DEST/content/shared.js"

echo -e "         ${GRAY}icons/icon128.png${NC}"
mkdir -p "$DEST/$(dirname "icons/icon128.png")"
echo "" | base64 -d > "$DEST/icons/icon128.png"

echo -e "         ${GRAY}icons/icon16.png${NC}"
mkdir -p "$DEST/$(dirname "icons/icon16.png")"
echo "iVBORw0KGgoAAAANSUhEUgAAABAAAAAQCAYAAAAf8/9hAAAAlklEQVR4nLWTwQ2AIAxFqfHqFHIxYQhHZwgSLjAFA+BBMUD7SYixx9L/+ilUqY9B8MTlwHKGdJ9akXA7j70/SgVagVoHLgdJyEDWxwJZZsWvu8cNv0LbqRaJNYS612IESdbHhVUBMcqLgJn4B4AGJuVvgCGdrI+jYmmAypAePiNywh0AFyjqn8iXabQLpQHcBQHUhLCNF28MRNzBVwW5AAAAAElFTkSuQmCC" | base64 -d > "$DEST/icons/icon16.png"

echo -e "         ${GRAY}icons/icon48.png${NC}"
mkdir -p "$DEST/$(dirname "icons/icon48.png")"
echo "" | base64 -d > "$DEST/icons/icon48.png"

echo -e "         ${GRAY}manifest.json${NC}"
mkdir -p "$DEST/$(dirname "manifest.json")"
echo "" | base64 -d > "$DEST/manifest.json"

echo -e "         ${GRAY}options.html${NC}"
mkdir -p "$DEST/$(dirname "options.html")"
echo "" | base64 -d > "$DEST/options.html"

echo -e "         ${GRAY}popup.html${NC}"
mkdir -p "$DEST/$(dirname "popup.html")"
echo "" | base64 -d > "$DEST/popup.html"

echo -e "         ${GRAY}popup.js${NC}"
mkdir -p "$DEST/$(dirname "popup.js")"
echo "" | base64 -d > "$DEST/popup.js"

echo -e "         ${GRAY}src/background.js${NC}"
mkdir -p "$DEST/$(dirname "src/background.js")"
echo "" | base64 -d > "$DEST/src/background.js"


echo -e "         ${GREEN}✅ 14 Dateien geschrieben${NC}"

# ── STEP 3: CHROME FINDEN ────────────────────────────────────────────
echo -e "  ${YELLOW}[3/4]${NC} Suche Chrome..."
CHROME=""
for p in \
    "/usr/bin/google-chrome" \
    "/usr/bin/google-chrome-stable" \
    "/usr/bin/chromium-browser" \
    "/usr/bin/chromium" \
    "/snap/bin/chromium" \
    "/snap/bin/google-chrome"; do
    if [ -x "$p" ]; then CHROME="$p"; break; fi
done

if [ -n "$CHROME" ]; then
    echo -e "         ${GREEN}✅ $CHROME${NC}"
else
    echo -e "         ${YELLOW}⚠️  Chrome nicht gefunden${NC}"
fi

# ── STEP 4: CHROME ÖFFNEN ────────────────────────────────────────────
echo -e "  ${YELLOW}[4/4]${NC} Öffne Chrome + Dateimanager..."
if [ -n "$CHROME" ]; then
    "$CHROME" "chrome://extensions" &>/dev/null &
    sleep 1
fi

# Dateimanager öffnen
if command -v xdg-open &>/dev/null; then
    xdg-open "$DEST" &>/dev/null &
elif command -v nautilus &>/dev/null; then
    nautilus "$DEST" &>/dev/null &
fi

echo ""
echo -e "  ${GREEN}╔══════════════════════════════════════════════════════════╗${NC}"
echo -e "  ${GREEN}║  ✅ FAST FERTIG — noch 3 Klicks in Chrome:              ║${NC}"
echo -e "  ${GREEN}║                                                          ║${NC}"
echo -e "  ║  1. Entwicklermodus einschalten  (Toggle oben rechts)   ║"
echo -e "  ║  2. 'Entpackte Erweiterung laden' klicken               ║"
echo -e "  ║  3. Ordner wählen:                                       ║"
echo -e "  ║     $DEST"
echo -e "  ${GREEN}║                                                          ║${NC}"
echo -e "  ${GREEN}╚══════════════════════════════════════════════════════════╝${NC}"
echo ""
echo -e "  ${GRAY}Drücke Enter zum Beenden...${NC}"
read
